export type JobStatus = "PENDING" | "RUNNING" | "COMPLETED" | "FAILED" | "CANCELLED" | "TIMED_OUT"

export interface Job<T> {
  id: string
  data: T
  status: JobStatus
  leaseExpiresAt: number
}

export class DistributedWorkerQueue<T> {
  private jobs = new Map<string, Job<T>>()
  private timers = new Map<string, NodeJS.Timeout>()
  private leaseDurationMs: number

  constructor(leaseDurationMs = 5000) {
    this.leaseDurationMs = leaseDurationMs
  }

  submitJob(id: string, data: T): Job<T> {
    const job: Job<T> = {
      id,
      data,
      status: "PENDING",
      leaseExpiresAt: 0,
    }
    this.jobs.set(id, job)
    return job
  }

  startJob(id: string): Job<T> | null {
    const job = this.jobs.get(id)
    if (!job || job.status !== "PENDING") return null
    job.status = "RUNNING"
    job.leaseExpiresAt = Date.now() + this.leaseDurationMs

    // Start heartbeat lease renewal
    const timer = setInterval(() => {
      this.renewLease(id)
    }, Math.floor(this.leaseDurationMs / 2))
    this.timers.set(id, timer)
    return job
  }

  // BUG 1: Race condition — does not check if job was cancelled or already timed out
  renewLease(id: string): boolean {
    const job = this.jobs.get(id)
    if (!job) return false
    job.leaseExpiresAt = Date.now() + this.leaseDurationMs
    return true
  }

  // BUG 2: Memory leak — does not clear interval timer on completion or cancellation
  completeJob(id: string): void {
    const job = this.jobs.get(id)
    if (job) job.status = "COMPLETED"
  }

  cancelJob(id: string): void {
    const job = this.jobs.get(id)
    if (job) job.status = "CANCELLED"
  }

  isLeaseValid(id: string): boolean {
    const job = this.jobs.get(id)
    if (!job || job.status !== "RUNNING") return false
    return Date.now() < job.leaseExpiresAt
  }
}

